function minEatingSpeedImpl(piles, h) {
  function check(k) {
    let hours = 0;
    for (const pile of piles) hours += Math.ceil(pile / k);
    return hours <= h;
  }
  let lo = 1, hi = Math.max(...piles);
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (check(mid)) hi = mid; else lo = mid + 1;
  }
  return lo;
}

function shipWithinDaysImpl(weights, days) {
  function check(cap) {
    let parts = 1, curr = 0;
    for (const w of weights) {
      if (curr + w > cap) { parts++; curr = 0; }
      curr += w;
      if (parts > days) return false;
    }
    return true;
  }
  let lo = Math.max(...weights), hi = weights.reduce((a,b)=>a+b,0);
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (check(mid)) hi = mid; else lo = mid + 1;
  }
  return lo;
}

