function findMedianSortedArraysImpl(nums1, nums2) {
  if (nums1.length > nums2.length) return findMedianSortedArraysImpl(nums2, nums1);
  const m = nums1.length, n = nums2.length;
  const half = Math.floor((m + n + 1) / 2);
  let lo = 0, hi = m;
  while (lo <= hi) {
    const i = lo + Math.floor((hi - lo) / 2);
    const j = half - i;
    const ml1 = i === 0 ? -Infinity : nums1[i-1];
    const mr1 = i === m ?  Infinity : nums1[i];
    const ml2 = j === 0 ? -Infinity : nums2[j-1];
    const mr2 = j === n ?  Infinity : nums2[j];
    if (ml1 <= mr2 && ml2 <= mr1) {
      if ((m + n) % 2 === 1) return Math.max(ml1, ml2);
      return (Math.max(ml1, ml2) + Math.min(mr1, mr2)) / 2;
    } else if (ml1 > mr2) hi = i - 1;
    else lo = i + 1;
  }
  return 0;
}

