function splitArrayImpl(nums, k) {
  function canSplit(maxSum) {
    let parts = 1, curr = 0;
    for (const num of nums) {
      if (curr + num > maxSum) { parts++; curr = 0; if (parts > k) return false; }
      curr += num;
    }
    return true;
  }
  let lo = Math.max(...nums), hi = nums.reduce((a,b)=>a+b, 0);
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (canSplit(mid)) hi = mid; else lo = mid + 1;
  }
  return lo;
}

