const MODULE6_PROBLEMS = {
  875:  {pattern:'answer-space min'}, 153: {pattern:'rotated binary'},
  154:  {pattern:'rotated + hi--'},  33:  {pattern:'rotated binary'},
  81:   {pattern:'rotated + hi--'},  4:   {pattern:'partition binary'},
  410:  {pattern:'answer-space min'},1011:{pattern:'answer-space min'},
  74:   {pattern:'index binary 2D'}
};

function classifyBinarySearch(signal) {
  const map = {
    'minimum X such that': 'answer-space min',
    'maximum X such that': 'answer-space max',
    'sorted rotated no dup': 'rotated binary',
    'sorted rotated with dup': 'rotated + hi--',
    'median two sorted': 'partition binary',
    'find in sorted 2D matrix': 'index binary 2D'
  };
  return map[signal] || 'unknown';
}

function module6Summary() {
  const vals = Object.values(MODULE6_PROBLEMS);
  return {
    total: vals.length,
    answerSpaceMin: vals.filter(p=>p.pattern==='answer-space min').length,
    rotated: vals.filter(p=>p.pattern.startsWith('rotated')).length,
    special: vals.filter(p=>!p.pattern.startsWith('rotated')&&p.pattern!=='answer-space min').length
  };
}

function isSamePatternFamily(id1, id2) {
  const p1 = MODULE6_PROBLEMS[id1], p2 = MODULE6_PROBLEMS[id2];
  if (!p1 || !p2) return false;
  return p1.pattern === p2.pattern;
}
